// 安装最新版本的 DashScope SDK
import com.alibaba.dashscope.aigc.multimodalconversation.AudioParameters;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversation;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversationParam;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversationResult;
import com.alibaba.dashscope.exception.ApiException;
import com.alibaba.dashscope.exception.NoApiKeyException;
import com.alibaba.dashscope.exception.UploadFileException;
import com.alibaba.dashscope.utils.JsonUtils;
import com.alibaba.dashscope.utils.Constants;

public class Main {
  // 如需使用指令控制功能，请将 MODEL 替换为 qwen3-tts-instruct-flash
  private static final String MODEL = "qwen3-tts-flash";
  public static void call() throws ApiException, NoApiKeyException, UploadFileException {
    MultiModalConversation conv = new MultiModalConversation();
    MultiModalConversationParam param = MultiModalConversationParam.builder()
        .model(MODEL)
        // 如果未配置环境变量，请将以下行替换为您的 API 密钥：apiKey("sk-xxx")
        .apiKey(System.getenv("DASHSCOPE_API_KEY"))
        .text("Today is a wonderful day to build something people love!")
        .voice(AudioParameters.Voice.CHERRY)
        .parameter("language_type", "English")
        // 如需使用指令控制功能，请取消以下行的注释，并将模型替换为 qwen3-tts-instruct-flash
        // .parameter("instructions","Fast speech rate, with a clear rising intonation, suitable for introducing fashion products.")
        // .parameter("optimize_instructions",true)
        .build();
    MultiModalConversationResult result = conv.call(param);
    System.out.println(JsonUtils.toJson(result));
  }
  public static void main(String[] args) {
    Constants.baseHttpApiUrl = "https://dashscope.aliyuncs.com/api/v1";
    try {
      call();
    } catch (ApiException | NoApiKeyException | UploadFileException e) {
      System.out.println(e.getMessage());
    }
    System.exit(0);
  }
}

// DashScope SDK 版本 2.19.0 或更高版本
import com.alibaba.dashscope.aigc.multimodalconversation.AudioParameters;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversation;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversationParam;
import com.alibaba.dashscope.aigc.multimodalconversation.MultiModalConversationResult;
import com.alibaba.dashscope.exception.ApiException;
import com.alibaba.dashscope.exception.NoApiKeyException;
import com.alibaba.dashscope.exception.UploadFileException;
import com.alibaba.dashscope.utils.JsonUtils;
import io.reactivex.Flowable;
import com.alibaba.dashscope.utils.Constants;

public class Main {
  // 如需使用指令控制功能，请将 MODEL 设置为 qwen3-tts-instruct-flash
  private static final String MODEL = "qwen3-tts-flash";
  public static void streamCall() throws ApiException, NoApiKeyException, UploadFileException {
    MultiModalConversation conv = new MultiModalConversation();
    MultiModalConversationParam param = MultiModalConversationParam.builder()
        .model(MODEL)
        // 如果未设置环境变量，请将以下行替换为：.apiKey("sk-xxx")
        .apiKey(System.getenv("DASHSCOPE_API_KEY"))
        .text("Today is a wonderful day to build something people love!")
        .voice(AudioParameters.Voice.CHERRY)
        .parameter("language_type", "English")
        // 如需使用指令控制功能，请取消以下行的注释，并将模型设置为 qwen3-tts-instruct-flash
        // .parameter("instructions","Speak quickly with a clear rising intonation, suitable for promoting fashion items.")
        // .parameter("optimize_instructions",true)
        .build();
    Flowable<MultiModalConversationResult> result = conv.streamCall(param);
    result.blockingForEach(r -> {System.out.println(JsonUtils.toJson(r));
    });
  }
  public static void main(String[] args) {
    Constants.baseHttpApiUrl = "https://dashscope.aliyuncs.com/api/v1";
    try {
      streamCall();
    } catch (ApiException | NoApiKeyException | UploadFileException e) {
      System.out.println(e.getMessage());
    }
    System.exit(0);
  }
}

